import json, os, re, sys, glob, hashlib

DIRS = [
    "/home/shadeform/.claude/projects/-home-shadeform-gpumode",
    "/home/shadeform/.claude/projects/-home-shadeform",
]

# Build candidate file list: top-level + subagents under cff4df73, that contain the run marker
MARKER = "2026-06-22-09-10-03-qr_v2"
files = set()
for d in DIRS:
    for root, _, fns in os.walk(d):
        # skip tool-results dirs (those are raw tool outputs, not assistant msgs)
        if "/tool-results" in root:
            continue
        for fn in fns:
            if fn.endswith(".jsonl"):
                files.add(os.path.join(root, fn))

# Filter to files that mention the marker (fast grep-like check)
cand = []
for f in sorted(files):
    try:
        with open(f, "rb") as fh:
            blob = fh.read()
        if MARKER.encode() in blob:
            cand.append(f)
    except Exception:
        pass

print(f"# candidate files containing marker: {len(cand)}", file=sys.stderr)

# Iterate assistant text blocks
def iter_assistant_texts(f):
    with open(f, "r", errors="replace") as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            if '"type":"assistant"' not in line and '"type": "assistant"' not in line:
                continue
            try:
                d = json.loads(line)
            except Exception:
                continue
            if d.get("type") != "assistant":
                continue
            ts = d.get("timestamp", "")
            msg = d.get("message", {})
            content = msg.get("content", [])
            if isinstance(content, str):
                yield ts, content
                continue
            if not isinstance(content, list):
                continue
            for block in content:
                if isinstance(block, dict) and block.get("type") == "text":
                    txt = block.get("text", "")
                    if txt:
                        yield ts, txt

# category patterns (case-insensitive)
patterns = {
  "earlyterm": re.compile(r"should i (keep going|continue|proceed|stop)|shall i proceed|let me know if you (want|would like) me to continue|do you want me to|would you like me to|this seems like a good place to stop|i'll stop here|i will stop here|nothing left to optimize|the (experiment|run) (has )?converged|we'?re done|i've exhausted|i have exhausted|waiting for (your |user )?(input|confirmation|instruction)|awaiting (your |user )?(input|confirmation|instruction)|pause the run|stop the run|halt the run", re.I),
  "deaths": re.compile(r"connection error|api error|overloaded|rate limit|\b429\b|\b500\b|\b529\b|respawn|worker (died|death)|restart(ing)? worker|brief_stop|brief stop|disconnect|timed out|timeout|503|502", re.I),
  "venv": re.compile(r"torch 2\.12|2\.12\.1|cu130|venv upgrade|maintenance window|pip install torch|torch==2\.12|upgrade.{0,20}torch|torch.{0,20}upgrade", re.I),
  "spindown": re.compile(r"spin-?down|spin down|no new brief|let (the )?workers finish|graceful|winding down|wind down|wind-down", re.I),
}

# Collect matches, dedup by (category, normalized-text-hash)
from collections import defaultdict
matches = {k: [] for k in patterns}
seen = {k: set() for k in patterns}

def norm(t):
    return re.sub(r"\s+", " ", t).strip().lower()

for f in cand:
    short = f.replace("/home/shadeform/.claude/projects/", "")
    for ts, txt in iter_assistant_texts(f):
        for cat, pat in patterns.items():
            m = pat.search(txt)
            if m:
                h = hashlib.md5(norm(txt).encode()).hexdigest()
                if h in seen[cat]:
                    continue
                seen[cat].add(h)
                matches[cat].append((ts, short, txt, m.group(0)))

# Print summary counts
for cat in patterns:
    print(f"\n===== {cat}: {len(matches[cat])} unique matches =====")

# Save full to a json for further drilldown
with open("/tmp/scan_out.json", "w") as out:
    json.dump({cat: [{"ts": t, "file": fl, "text": tx, "hit": h} for (t, fl, tx, h) in matches[cat]] for cat in matches}, out)
print("\nSaved /tmp/scan_out.json", file=sys.stderr)
